/**
 * Test fixtures generated by `pnpm exec tsx scripts/generate-fixtures.ts` (committed).
 * Markers are read by the mock face/moderation providers (src/providers/mock/markers.ts).
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import type { Marker } from "@/providers/mock/markers";

export const FIXTURES_DIR = path.dirname(fileURLToPath(import.meta.url));

export const ALICE_SELFIES = Array.from({ length: 12 }, (_, i) => `alice-${String(i + 1).padStart(2, "0")}` as const);

/**
 * The mock "default" identity: what the mock face provider sees in unmarked images, e.g. the
 * Chromium fake-camera frame of the e2e consent selfie. Use these as that user's training photos.
 */
export const DEFAULT_IDENTITY_SELFIES = Array.from(
  { length: 12 },
  (_, i) => `default-${String(i + 1).padStart(2, "0")}` as const,
);

const ALICE = { identity: "alice", age: 29, faces: 1, nsfw: false, blurry: false, publicFigure: false } as const;

/** Expected marker of every selfie fixture (`tests/fixtures/selfies/<name>.jpg`). */
export const SELFIE_MARKERS: Record<string, Marker> = {
  ...Object.fromEntries(ALICE_SELFIES.map((n) => [n, { ...ALICE }])),
  ...Object.fromEntries(DEFAULT_IDENTITY_SELFIES.map((n) => [n, { ...ALICE, identity: "default" }])),
  "bob-01": { ...ALICE, identity: "bob", age: 34 },
  "teen-01": { ...ALICE, age: 15 },
  "group-01": { ...ALICE, faces: 2 },
  "blurry-01": { ...ALICE, blurry: true },
  "dark-01": { ...ALICE },
  "nsfw-01": { ...ALICE, nsfw: true },
  "celebrity-01": { ...ALICE, identity: "oscar", age: 45, publicFigure: true },
};
export type SelfieName = keyof typeof SELFIE_MARKERS;

/** Expected marker of the other fixtures (null = unmarked). */
export const OTHER_FIXTURE_MARKERS: Record<string, Marker | null> = {
  "garment.jpg": { ...ALICE, identity: "default", age: 30, faces: 0 },
  "reference-pose.jpg": { ...ALICE, identity: "judy", age: 31 },
  "mask.png": null,
};

/** Bytes of a fixture by relative path, e.g. "garment.jpg" or "selfies/alice-01.jpg". */
export function readFixture(relativePath: string): Uint8Array {
  return new Uint8Array(readFileSync(path.join(FIXTURES_DIR, relativePath)));
}

export function readSelfie(name: SelfieName): Uint8Array {
  return readFixture(`selfies/${name}.jpg`);
}
